    const formatDate = inject('formatDate')
    const refreshButton = inject('refreshButton')
    const cardShimmer = inject('cardShimmer')
    const graphShimmer = inject('graphShimmer')
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const loading = ref(false);

    const costComparisonOptions = computed(() => {
  const is_dark = false;
  return {
    chart: {
      type: 'bar',
      toolbar: { show: false },
      fontFamily: 'inherit',
      height: 350
    },
    plotOptions: {
      bar: {
        horizontal: false,
        columnWidth: '55%',
        borderRadius: 4,
        distributed: true
      }
    },
    colors: ['#2ecc71','#3498db', '#2d3436', '#f39c12' ],
    xaxis: {
      categories: [ 'FUEL', 'SPARES', 'TYRES', 'MAINTENANCES'],
      labels: {
        style: {
          colors: is_dark ? '#888ea8' : '#3b3f5c',
          fontSize: '12px'
        }
      }
    },
    yaxis: {
      labels: {
        style: {
          colors: is_dark ? '#888ea8' : '#3b3f5c',
          fontSize: '12px'
        },
        formatter: function(val) {
          return formatNumber(val);
        }
      }
    },
    legend: {
      show: false
    },
    tooltip: {
      theme: is_dark ? 'dark' : 'light',
      y: {
        formatter: function(val) {
          return formatNumber(val);
        }
      }
    },
    grid: {
      borderColor: is_dark ? '#191e3a' : '#e0e6ed',
      strokeDashArray: 3
    },
    dataLabels: {
      enabled: false
    }
  };
});


const costComparisonReport = ref([
  { name: 'Cost : ', data: [0, 0, 0, 0] }
]);



    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },       
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });



const profile = ref('')
const showConfirmation = inject('showConfirmation');
const getProfile = async() =>{
    loading.value = true
    try{
    const response = await axiosInstance.get(`asset-profile?asset_id=${route.params.asset_id}`)
    profile.value = response.data;
    costComparisonReport.value = [
  {
    name: 'Cost : ',
    data: [
      response.data.cost_summary.fuel,
      response.data.cost_summary.spares,
      response.data.cost_summary.tyres,
      response.data.cost_summary.maintenances,
    ]
  }
];

    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}

 
    onMounted(() => {
         getProfile()
    });

</script>

